import Foundation

protocol ExerciseService {
    func fetchExercises(type: WorkoutType?) async throws -> [Exercise]
}

enum ExerciseServiceError: Error, LocalizedError, Equatable {
    case emptyData

    var errorDescription: String? {
        switch self {
        case .emptyData:
            return "Не удалось загрузить упражнения"
        }
    }
}

final class MockExerciseService: ExerciseService {
    func fetchExercises(type: WorkoutType?) async throws -> [Exercise] {
        try await Task.sleep(nanoseconds: 250_000_000)
        let items = Exercise.mockExercises
        guard let type else { return items }
        let filtered = items.filter { $0.type == type }
        return filtered.isEmpty ? items : filtered
    }
}

